/* Project page behaviour: BibTeX copy, scroll-to-top, and the interactive
   move-structure figure. No dependencies. The figure data comes from
   page_data.js, generated by comparative_analysis/export_page_data.py. */
(function () {
  "use strict";

  /* ------------------------------------------------------------ BibTeX copy */
  function copyBibTeX() {
    var code = document.getElementById("bibtex-code");
    var button = document.querySelector(".copy-bibtex-btn");
    if (!code || !button) return;
    var label = button.querySelector(".copy-text");
    var text = code.textContent;

    function done() {
      button.classList.add("copied");
      label.textContent = "Copied";
      window.setTimeout(function () {
        button.classList.remove("copied");
        label.textContent = "Copy";
      }, 2000);
    }

    function fallback() {
      var area = document.createElement("textarea");
      area.value = text;
      area.setAttribute("readonly", "");
      area.style.position = "fixed";
      area.style.opacity = "0";
      document.body.appendChild(area);
      area.select();
      try {
        document.execCommand("copy");
        done();
      } finally {
        document.body.removeChild(area);
      }
    }

    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(done, fallback);
    } else {
      fallback();
    }
  }

  /* ---------------------------------------------------------- scroll to top */
  function setupScrollTop() {
    var button = document.querySelector(".scroll-to-top");
    if (!button) return;
    button.addEventListener("click", function () {
      window.scrollTo({ top: 0, behavior: "smooth" });
    });
    function update() {
      button.classList.toggle("visible", window.scrollY > 400);
    }
    window.addEventListener("scroll", update, { passive: true });
    update();
  }

  /* ------------------------------------------------- move-structure figure */
  var MOVE_NAMES = { 1: "Move 1, territory", 2: "Move 2, niche", 3: "Move 3, occupying" };
  var MOVE_VARS = { 1: "var(--move-1)", 2: "var(--move-2)", 3: "var(--move-3)" };
  var MODELS = [
    { id: "chatgpt", label: "ChatGPT" },
    { id: "claude", label: "Claude" },
    { id: "gemma", label: "Gemma" },
    { id: "qwen", label: "Qwen" }
  ];

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function sequenceOf(intro) {
    return intro.seq.map(function (unit) { return unit[0]; }).join("-");
  }

  function totalWords(intro) {
    return intro.seq.reduce(function (sum, unit) { return sum + unit[1]; }, 0);
  }

  function setupStructureFigure() {
    var root = document.getElementById("structure-figure");
    var data = window.PAGE_DATA;
    if (!root || !data) return;

    var byKey = {};
    data.sources.forEach(function (source) {
      byKey[source.model ? source.model + "|" + source.mode : "original"] = source;
    });

    var state = { model: "claude", order: "structure" };
    var panelsEl = root.querySelector(".strip-panels");
    var tableBody = root.querySelector(".table-view tbody");
    var tableHead = root.querySelector(".table-view thead tr");
    var tooltip = el("div", "viz-tooltip");
    tooltip.setAttribute("role", "status");
    document.body.appendChild(tooltip);

    function sources() {
      return [byKey.original, byKey[state.model + "|basic"], byKey[state.model + "|cars_guided"]];
    }

    /* Row order. "structure": the most frequent move sequence first, so
       repeated templates form visible blocks. "paper": the same paper on the
       same row in all three panels. */
    function ordered(source) {
      var rows = source.intros.slice();
      if (state.order === "paper") {
        rows.sort(function (a, b) { return a.id < b.id ? -1 : 1; });
        return rows;
      }
      var counts = {};
      rows.forEach(function (row) {
        var key = sequenceOf(row);
        counts[key] = (counts[key] || 0) + 1;
      });
      rows.sort(function (a, b) {
        var ka = sequenceOf(a), kb = sequenceOf(b);
        if (counts[kb] !== counts[ka]) return counts[kb] - counts[ka];
        if (ka !== kb) return ka.length - kb.length || (ka < kb ? -1 : 1);
        return a.id < b.id ? -1 : 1;
      });
      return rows;
    }

    function showTooltip(strip, intro, source) {
      var words = totalWords(intro);
      var share = { 1: 0, 2: 0, 3: 0 };
      intro.seq.forEach(function (unit) { share[unit[0]] += unit[1]; });

      tooltip.textContent = "";
      tooltip.appendChild(el("div", "tt-value", sequenceOf(intro)));
      tooltip.appendChild(el("div", "tt-label",
        source.label + " · paper " + intro.id + " (" + intro.q + ") · " + words + " words"));
      var title = data.titles[intro.id];
      if (title) tooltip.appendChild(el("div", "tt-label", title));
      var rows = el("div", "tt-rows");
      [1, 2, 3].forEach(function (move) {
        var key = el("span", "tt-key");
        key.style.background = MOVE_VARS[move];
        rows.appendChild(key);
        rows.appendChild(el("span", "tt-label", MOVE_NAMES[move]));
        rows.appendChild(el("span", "tt-num", Math.round(100 * share[move] / words) + "%"));
      });
      tooltip.appendChild(rows);

      var box = strip.getBoundingClientRect();
      tooltip.classList.add("is-visible");
      var tip = tooltip.getBoundingClientRect();
      var left = Math.min(Math.max(8, box.left + box.width / 2 - tip.width / 2),
                          window.innerWidth - tip.width - 8);
      var top = box.top - tip.height - 10;
      if (top < 8) top = box.bottom + 10;
      tooltip.style.left = left + "px";
      tooltip.style.top = top + "px";
    }

    function hideTooltip() {
      tooltip.classList.remove("is-visible");
    }

    function renderPanel(source, index) {
      var panel = el("div", "strip-panel");
      panel.appendChild(el("h4", null, source.label));
      panel.appendChild(el("p", "panel-sub",
        index === 0 ? "76 published introductions" : "76 generated, same papers"));

      var strips = el("div", "strips");
      strips.setAttribute("tabindex", "0");
      strips.setAttribute("role", "img");
      strips.setAttribute("aria-label",
        source.label + ": move structure of 76 introductions, one row each. " +
        source.structures + " distinct move structures, " + source.canonical +
        " follow the plain 1-2-3 order. Use the arrow keys to read single rows, " +
        "or open the table below.");

      var rows = ordered(source);
      var active = -1;

      function setActive(i) {
        var children = strips.children;
        if (active >= 0 && children[active]) children[active].classList.remove("is-active");
        active = i;
        if (i < 0) {
          strips.classList.remove("has-active");
          hideTooltip();
          return;
        }
        strips.classList.add("has-active");
        children[i].classList.add("is-active");
        showTooltip(children[i], rows[i], source);
      }

      rows.forEach(function (intro, i) {
        var strip = el("div", "strip");
        intro.seq.forEach(function (unit) {
          var block = el("span", "unit is-m" + unit[0]);
          block.style.flex = unit[1] + " 1 0";
          strip.appendChild(block);
        });
        strip.addEventListener("pointerenter", function () { setActive(i); });
        strips.appendChild(strip);
      });

      strips.addEventListener("pointerleave", function () { setActive(-1); });
      strips.addEventListener("blur", function () { setActive(-1); });
      strips.addEventListener("keydown", function (event) {
        var next = active;
        if (event.key === "ArrowDown") next = Math.min(rows.length - 1, active + 1);
        else if (event.key === "ArrowUp") next = Math.max(0, active - 1);
        else if (event.key === "Home") next = 0;
        else if (event.key === "End") next = rows.length - 1;
        else if (event.key === "Escape") next = -1;
        else return;
        event.preventDefault();
        setActive(next);
      });
      panel.appendChild(strips);

      var stats = el("div", "panel-stats");
      [[source.structures, "distinct move structures"],
       [source.canonical + " of 76", "follow the plain 1-2-3 order"]].forEach(function (pair) {
        var stat = el("div", "panel-stat");
        stat.appendChild(el("span", "stat-value", String(pair[0])));
        stat.appendChild(el("span", "stat-label", pair[1]));
        stats.appendChild(stat);
      });
      panel.appendChild(stats);
      return panel;
    }

    function renderTable() {
      var list = sources();
      tableHead.textContent = "";
      tableHead.appendChild(el("th", null, "Paper"));
      list.forEach(function (source) { tableHead.appendChild(el("th", null, source.label)); });

      var lookup = list.map(function (source) {
        var map = {};
        source.intros.forEach(function (intro) { map[intro.id] = intro; });
        return map;
      });
      tableBody.textContent = "";
      Object.keys(lookup[0]).sort().forEach(function (id) {
        var row = el("tr");
        row.appendChild(el("th", null, id));
        lookup.forEach(function (map) { row.appendChild(el("td", null, sequenceOf(map[id]))); });
        tableBody.appendChild(row);
      });
    }

    function render() {
      hideTooltip();
      panelsEl.textContent = "";
      sources().forEach(function (source, index) {
        panelsEl.appendChild(renderPanel(source, index));
      });
      renderTable();
    }

    function bindSegmented(name, key) {
      var group = root.querySelector('[data-control="' + name + '"]');
      group.addEventListener("click", function (event) {
        var button = event.target.closest("button[data-value]");
        if (!button) return;
        state[key] = button.dataset.value;
        Array.prototype.forEach.call(group.querySelectorAll("button"), function (b) {
          b.setAttribute("aria-pressed", String(b === button));
        });
        render();
      });
    }

    var modelGroup = root.querySelector('[data-control="model"]');
    MODELS.forEach(function (model) {
      var button = el("button", null, model.label);
      button.type = "button";
      button.dataset.value = model.id;
      button.setAttribute("aria-pressed", String(model.id === state.model));
      modelGroup.appendChild(button);
    });

    bindSegmented("model", "model");
    bindSegmented("order", "order");
    window.addEventListener("scroll", hideTooltip, { passive: true });
    render();
  }

  document.addEventListener("DOMContentLoaded", function () {
    var copy = document.querySelector(".copy-bibtex-btn");
    if (copy) copy.addEventListener("click", copyBibTeX);
    setupScrollTop();
    setupStructureFigure();
  });
})();
